import asyncio
import os

import pytest
from alembic import command
from alembic.config import Config

pytestmark = [
    pytest.mark.skipif(
        os.getenv("NEWSINTEL_RUN_POSTGRES_TESTS") != "1",
        reason="requires the PostgreSQL fixture stack",
    ),
    pytest.mark.asyncio(loop_scope="session"),
]


async def test_models_match_migrations() -> None:
    # The models are what a reader and the next autogenerated migration see; the migrations are what
    # the database is. Any column type, index or constraint in one and not the other fails here.
    config = Config("alembic.ini")
    await asyncio.to_thread(command.upgrade, config, "head")
    await asyncio.to_thread(command.check, config)
